import { strict as assert } from "assert";
import * as fs from "fs";
import * as path from "path";
import type { WitnessTester } from "circomkit";
import { circomkit } from "../common/index.ts";
import { witnessValues } from "../common/witness-signals.ts";
import { PROD_PARAMS } from "../common/jsonld-fixture.ts";

// Generated by `yarn generate:inputs:jsonld`.
const inputsDir = path.resolve(__dirname, "../../inputs");

function load(file: string): any {
  const raw = JSON.parse(fs.readFileSync(path.join(inputsDir, file), "utf8"));
  const big = (v: any): any => (Array.isArray(v) ? v.map(big) : BigInt(v));
  return Object.fromEntries(Object.entries(raw).map(([k, v]) => [k, big(v)]));
}

describe("jsonld prepare + Show linkage", () => {
  let prepare: WitnessTester<any, any>;
  let show: WitnessTester<any, any>;

  before(async () => {
    prepare = await circomkit.WitnessTester("jsonld", {
      file: "jsonld",
      template: "JSONLD",
      params: [...PROD_PARAMS],
      recompile: true,
    });
    show = await circomkit.WitnessTester("show", {
      file: "show",
      template: "Show",
      params: [2, 2, 8, 64],
      recompile: true,
    });
  });

  it("the generated prepare inputs are accepted", async () => {
    const witness = await prepare.calculateWitness(load("jsonld/default.json"));
    await prepare.expectConstraintPass(witness);
  });

  it("Show's shared inputs equal the prepare circuit's shared signals", async () => {
    const pw = await prepare.calculateWitness(load("jsonld/default.json"));
    const showInputs = load("show/jsonld.json");
    const [dx, dy, v0, v1, h0, h1] = await witnessValues(prepare, pw, [
      "main.deviceKeyX",
      "main.deviceKeyY",
      "main.normalizedClaimValues[0]",
      "main.normalizedClaimValues[1]",
      "main.claimIdentifierHashes[0]",
      "main.claimIdentifierHashes[1]",
    ]);
    assert.equal(dx, showInputs.deviceKeyX);
    assert.equal(dy, showInputs.deviceKeyY);
    assert.deepEqual([v0, v1], showInputs.claimValues);
    assert.deepEqual([h0, h1], showInputs.claimIdentifierHashes);
  });

  it("Show evaluates dateOfBirth <= cutoff AND nationality == digest64('Ruritanian') to true", async () => {
    const inputs = load("show/jsonld.json");
    const witness = await show.calculateWitness(inputs);
    await show.expectConstraintPass(witness);
    const [result] = await witnessValues(show, witness, ["main.expressionResult"]);
    assert.equal(result, 1n);
  });

  it("Show evaluates to false when the date-of-birth cutoff is earlier than the credential's", async () => {
    const inputs = load("show/jsonld.json");
    inputs.predicateRhsValues = [19800101n, inputs.predicateRhsValues[1]];
    const witness = await show.calculateWitness(inputs);
    const [result] = await witnessValues(show, witness, ["main.expressionResult"]);
    assert.equal(result, 0n);
  });

  it("Show rejects a predicate named for another attribute than the slot's", async () => {
    const inputs = load("show/jsonld.json");
    inputs.predicateClaimNames = [inputs.predicateClaimNames[1], inputs.predicateClaimNames[0]];
    inputs.predicateClaimNameLens = [inputs.predicateClaimNameLens[1], inputs.predicateClaimNameLens[0]];
    await show.expectFail(inputs);
  });
});
